package com.ginga.naviai.auth.validation;

import javax.validation.Constraint;
import javax.validation.Payload;
import java.lang.annotation.Documented;
import java.lang.annotation.Retention;
import java.lang.annotation.Target;

import static java.lang.annotation.ElementType.FIELD;
import static java.lang.annotation.RetentionPolicy.RUNTIME;

@Documented
@Constraint(validatedBy = StrongPasswordValidator.class)
@Target({ FIELD })
@Retention(RUNTIME)
public @interface StrongPassword {
    String message() default "パスワードは英大文字・英小文字・数字・記号のうち3種以上を含む必要があります";
    Class<?>[] groups() default {};
    Class<? extends Payload>[] payload() default {};
}

package com.ginga.naviai.auth.validation;

import javax.validation.ConstraintValidator;
import javax.validation.ConstraintValidatorContext;

public class StrongPasswordValidator implements ConstraintValidator<StrongPassword, String> {

    @Override
    public void initialize(StrongPassword constraintAnnotation) { }

    @Override
    public boolean isValid(String value, ConstraintValidatorContext context) {
        if (value == null) return false;
        int categories = 0;
        if (value.matches(".*[A-Z].*")) categories++;
        if (value.matches(".*[a-z].*")) categories++;
        if (value.matches(".*[0-9].*")) categories++;
        if (value.matches(".*[^A-Za-z0-9].*")) categories++;
        return categories >= 3 && value.length() >= 8;
    }
}

package com.ginga.naviai.auth.dto;

import javax.validation.constraints.Email;
import javax.validation.constraints.NotBlank;
import javax.validation.constraints.Pattern;
import javax.validation.constraints.Size;
import com.ginga.naviai.auth.validation.StrongPassword;

public class RegisterRequest {

    @NotBlank
    @Size(min = 3, max = 30)
    private String username;

    @NotBlank
    @Email
    @Pattern(regexp = ".+@ginga\.info$", message = "メールアドレスは @ginga.info ドメインである必要があります")
    private String email;

    @NotBlank
    @Size(min = 8)
    @StrongPassword
    private String password;

    @Size(max = 100)
    private String displayName;

    public RegisterRequest() {}

    public String getUsername() { return username; }
    public void setUsername(String username) { this.username = username; }
    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }
    public String getPassword() { return password; }
