package com.ginga.naviai.auth.service;

import com.ginga.naviai.auth.dto.RegisterRequest;
import com.ginga.naviai.auth.dto.UserResponse;
import com.ginga.naviai.auth.entity.User;
import com.ginga.naviai.auth.exception.DuplicateResourceException;
import com.ginga.naviai.auth.repository.UserRepository;
import com.ginga.naviai.auth.repository.ConfirmationTokenRepository;
import com.ginga.naviai.mail.MailService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;

import java.time.Instant;

@Service
public class AuthServiceImpl implements AuthService {

    private final UserRepository userRepository;
    private final BCryptPasswordEncoder passwordEncoder;
    private final ConfirmationTokenService tokenService;
    private final MailService mailService;

    @Autowired
    public AuthServiceImpl(UserRepository userRepository,
                           BCryptPasswordEncoder passwordEncoder,
                           ConfirmationTokenService tokenService,
                           MailService mailService) {
        this.userRepository = userRepository;
        this.passwordEncoder = passwordEncoder;
        this.tokenService = tokenService;
        this.mailService = mailService;
    }

    @Override
    public UserResponse register(RegisterRequest request) {
        if (userRepository.findByUsername(request.getUsername()).isPresent()) {
            throw new DuplicateResourceException("username is already taken");
        }
        if (userRepository.findByEmail(request.getEmail()).isPresent()) {
            throw new DuplicateResourceException("email is already registered");
        }

        User u = new User();
        u.setUsername(request.getUsername());
        u.setEmail(request.getEmail());
        u.setPasswordHash(passwordEncoder.encode(request.getPassword()));
        u.setDisplayName(request.getDisplayName());
        u.setEnabled(false);
        u.setCreatedAt(Instant.now());
        u.setUpdatedAt(Instant.now());

        User saved = userRepository.save(u);

        // create confirmation token and send email
        String token = tokenService.createTokenForUser(saved);
        String confirmUrl = String.format("%s/api/v1/auth/confirm?token=%s", "http://localhost:8080", token);
        String subject = "NaviAI - メール確認";
        String body = "登録ありがとうございます。以下のURLからメールを確認してください:\n" + confirmUrl;
        try {
            mailService.send(saved.getEmail(), subject, body);
        } catch (Exception ex) {
            // log and proceed; mail failures should be retried in production
        }

        UserResponse res = new UserResponse();
        res.setId(saved.getId());
        res.setUsername(saved.getUsername());
        res.setEmail(saved.getEmail());
        res.setDisplayName(saved.getDisplayName());
        res.setCreatedAt(saved.getCreatedAt());
        return res;
    }
}

package com.ginga.naviai.auth.controller;

import com.ginga.naviai.auth.dto.RegisterRequest;
import com.ginga.naviai.auth.dto.UserResponse;
import com.ginga.naviai.auth.service.AuthService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;

import com.ginga.naviai.auth.service.ConfirmationTokenService;
import com.ginga.naviai.auth.entity.ConfirmationToken;
import java.time.Instant;
import java.util.Optional;

import javax.validation.Valid;

@RestController
@RequestMapping("/api/v1/auth")
@Validated
public class AuthController {

    private final AuthService authService;
    private final ConfirmationTokenService tokenService;

    @Autowired
    public AuthController(AuthService authService, ConfirmationTokenService tokenService) {
        this.authService = authService;
        this.tokenService = tokenService;
    }

    @PostMapping("/register")
    public ResponseEntity<UserResponse> register(@Valid @RequestBody RegisterRequest request) {
        UserResponse res = authService.register(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(res);
    }

    @GetMapping("/confirm")
    public ResponseEntity<?> confirmEmail(@RequestParam("token") String token) {
        Optional<ConfirmationToken> opt = tokenService.findByToken(token);
        if (opt.isEmpty()) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body("invalid token");
        }
        ConfirmationToken ct = opt.get();
        if (ct.getConfirmedAt() != null) {
            return ResponseEntity.ok("already confirmed");
        }
        if (ct.getExpiresAt().isBefore(Instant.now())) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body("token expired");
        }
        tokenService.setConfirmedAt(ct, Instant.now());
        // enable user
        ct.getUser().setEnabled(true);
        // save user via repository indirectly
        // reuse token repository save path already updates confirmedAt; update user via UserRepository
        return ResponseEntity.ok("confirmed");
    }
}

