package com.ginga.naviai.auth.validation;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class StrongPasswordValidatorTest {

    private final StrongPasswordValidator validator = new StrongPasswordValidator();

    @Test
    void validPassword_withThreeCategories_isValid() {
        assertTrue(validator.isValid("Abcdef1!", null)); // upper, lower, digit, symbol
        assertTrue(validator.isValid("ABCdefgh1", null)); // upper, lower, digit
        assertTrue(validator.isValid("abcd1!@#A", null));
    }

    @Test
    void invalidPassword_lessThanThreeCategories_or_short_isInvalid() {
        assertFalse(validator.isValid("abcdefg1", null)); // lower+digit only (2 categories)
        assertFalse(validator.isValid("ABCDEFGH", null)); // upper only
        assertFalse(validator.isValid("Ab1!", null)); // too short
        assertFalse(validator.isValid(null, null));
    }
}

package com.ginga.naviai.auth.service;

import com.ginga.naviai.auth.entity.ConfirmationToken;
import com.ginga.naviai.auth.entity.User;
import com.ginga.naviai.auth.repository.ConfirmationTokenRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.Instant;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
public class ConfirmationTokenServiceTest {

    @Mock
    private ConfirmationTokenRepository tokenRepository;

    @InjectMocks
    private ConfirmationTokenService tokenService;

    @Test
    void createTokenForUser_savesTokenAndReturnsString() {
        User u = new User();
        u.setId(5L);
        ArgumentCaptor<ConfirmationToken> cap = ArgumentCaptor.forClass(ConfirmationToken.class);
        when(tokenRepository.save(any(ConfirmationToken.class))).thenAnswer(inv -> inv.getArgument(0));

        String token = tokenService.createTokenForUser(u);
        assertNotNull(token);
        verify(tokenRepository, times(1)).save(cap.capture());
        ConfirmationToken saved = cap.getValue();
        assertEquals(u, saved.getUser());
        assertNotNull(saved.getExpiresAt());
    }

    @Test
    void findByToken_delegatesToRepository() {
        ConfirmationToken ct = new ConfirmationToken();
        ct.setToken("t1");
        when(tokenRepository.findByToken("t1")).thenReturn(Optional.of(ct));
        Optional<ConfirmationToken> res = tokenService.findByToken("t1");
        assertTrue(res.isPresent());
        assertEquals("t1", res.get().getToken());
    }

    @Test
    void setConfirmedAt_updatesAndSaves() {
        ConfirmationToken ct = new ConfirmationToken();
        ct.setToken("t2");
        tokenService.setConfirmedAt(ct, Instant.now());
        verify(tokenRepository, times(1)).save(ct);
        assertNotNull(ct.getConfirmedAt());
    }
}

package com.ginga.naviai.exception;

import com.ginga.naviai.auth.exception.DuplicateResourceException;
import org.junit.jupiter.api.Test;

import org.springframework.http.ResponseEntity;

import static org.junit.jupiter.api.Assertions.*;

public class GlobalExceptionHandlerTest {

    private final GlobalExceptionHandler handler = new GlobalExceptionHandler();

    @Test
    void handleDuplicate_returns409AndMessage() {
        DuplicateResourceException ex = new DuplicateResourceException("already exists");
        ResponseEntity<Object> resp = handler.handleDuplicate(ex);
        assertEquals(409, resp.getStatusCodeValue());
        assertNotNull(resp.getBody());
        assertTrue(resp.getBody().toString().contains("already exists"));
    }
}

