package com.ginga.naviai.mail;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Recover;
import org.springframework.retry.annotation.Retryable;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;
import org.springframework.core.task.TaskExecutor;

import java.util.concurrent.CompletableFuture;

@Service
public class SmtpMailService implements MailService {

    private static final Logger logger = LoggerFactory.getLogger(SmtpMailService.class);

    private final JavaMailSender mailSender;

    // test helper: allow simulating failures
    private static volatile boolean simulateFailure = false;

    public static void setSimulateFailure(boolean fail) { simulateFailure = fail; }
    public static boolean isSimulateFailure() { return simulateFailure; }

    @Autowired
    public SmtpMailService(JavaMailSender mailSender) {
        this.mailSender = mailSender;
    }

    @Override
    @Async("mailTaskExecutor")
    @Retryable(value = Exception.class, maxAttempts = 3, backoff = @Backoff(delay = 2000))
    public void send(String to, String subject, String body) {
        if (simulateFailure) {
            throw new RuntimeException("simulated mail failure");
        }
        SimpleMailMessage msg = new SimpleMailMessage();
        msg.setTo(to);
        msg.setSubject(subject);
        msg.setText(body);
        mailSender.send(msg);
        logger.info("sent mail to {} subject={}", to, subject);
    }

    @Recover
    public void recover(Exception ex, String to, String subject, String body) {
        logger.error("Failed to send mail to {} after retries: {}", to, ex.getMessage());
        // In production, enqueue for manual retry or save to a failure table for later processing
    }
}

package com.ginga.naviai.auth.controller;

import com.ginga.naviai.auth.entity.ConfirmationToken;
import com.ginga.naviai.auth.entity.User;
import com.ginga.naviai.auth.repository.ConfirmationTokenRepository;
import com.ginga.naviai.auth.repository.UserRepository;
import com.ginga.naviai.mail.SmtpMailService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.Optional;

@RestController
@RequestMapping("/api/v1/test")
public class TestSupportController {

    private final ConfirmationTokenRepository tokenRepo;
    private final UserRepository userRepo;

    @Autowired
    public TestSupportController(ConfirmationTokenRepository tokenRepo, UserRepository userRepo) {
        this.tokenRepo = tokenRepo;
        this.userRepo = userRepo;
    }

    @GetMapping("/token")
    public ResponseEntity<?> getTokenByEmail(@RequestParam("email") String email) {
        Optional<User> u = userRepo.findByEmail(email);
        if (u.isEmpty()) return ResponseEntity.notFound().build();
        Optional<ConfirmationToken> ct = tokenRepo.findAll().stream().filter(t -> t.getUser().getId().equals(u.get().getId())).findFirst();
        return ct.map(c -> ResponseEntity.ok(c.getToken())).orElseGet(() -> ResponseEntity.notFound().build());
    }

    @GetMapping("/user")
    public ResponseEntity<?> getUser(@RequestParam("email") String email) {
        Optional<User> u = userRepo.findByEmail(email);
        return u.map(ResponseEntity::ok).orElseGet(() -> ResponseEntity.notFound().build());
    }

    @PostMapping("/mail/fail")
    public ResponseEntity<?> setMailFail(@RequestParam("enable") boolean enable) {
        SmtpMailService.setSimulateFailure(enable);
        return ResponseEntity.ok().build();
    }
}

const fetch = require('node-fetch');

// Environment: set BASE_URL to the running backend (default: http://localhost:8080)
const BASE_URL = process.env.BASE_URL || 'http://localhost:8080';

function randomSuffix() {
  return Math.random().toString(36).substring(2, 8);
}

async function postRegister(payload) {
  const res = await fetch(`${BASE_URL}/api/v1/auth/register`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  const text = await res.text();
  let body = null;
  try { body = JSON.parse(text); } catch (e) { body = text; }
  return { status: res.status, body };
}

/* Test: 正常登録
   - 登録に必要な全フィールドを送り、201 Created とユーザー情報が返ることを確認する */
test('正常登録: returns 201 and user info', async () => {
  const suffix = randomSuffix();
  const payload = {
    username: `user_${suffix}`,
    email: `test_${suffix}@ginga.info`,
    password: 'Aa1!aaaa',
    displayName: 'テスト ユーザー'
  };
  const res = await postRegister(payload);
  expect(res.status).toBe(201);
  expect(res.body).toHaveProperty('id');
  expect(res.body.username).toBe(payload.username);
  expect(res.body.email).toBe(payload.email);
});

/* Test: メールドメイン検証
   - @ginga.info ドメイン以外のメールアドレスを送ると 400 を返す */
test('メールドメイン検証: invalid domain returns 400', async () => {
  const payload = {
    username: `user_bad_${randomSuffix()}`,
    email: `bad@other.com`,
    password: 'Aa1!aaaa',
    displayName: 'Bad Domain'
  };
  const res = await postRegister(payload);
  expect(res.status).toBe(400);
});

/* Test: パスワード強度検証
   - 8文字未満や要件未満のパスワードで 400 を返す */
test('弱パスワード: returns 400', async () => {
  const payload = {
    username: `user_weak_${randomSuffix()}`,
    email: `weak_${randomSuffix()}@ginga.info`,
    password: 'password',
    displayName: 'Weak Pass'
  };
  const res = await postRegister(payload);
  expect(res.status).toBe(400);
});

/* Test: 重複登録
   - 同一 email で2回登録試行すると2回目は 409 を返す */
test('重複登録: second registration with same email returns 409', async () => {
  const suffix = randomSuffix();
  const payload = {
    username: `userdup_${suffix}`,
    email: `dup_${suffix}@ginga.info`,
    password: 'Aa1!aaaa',
    displayName: 'Dup User'
  };
  const first = await postRegister(payload);
  expect(first.status).toBe(201);
  const secondPayload = { ...payload, username: `userdup2_${suffix}` };
  const second = await postRegister(secondPayload);
  expect(second.status).toBe(409);
});

/* Test: 確認トークンフロー
   - 登録後、テスト用APIでトークンを取得し、確認エンドポイントへアクセスするとユーザーが有効化される */
test('確認トークンフロー: register -> confirm -> user enabled', async () => {
  const suffix = randomSuffix();
  const email = `conf_${suffix}@ginga.info`;
  const payload = {
    username: `confuser_${suffix}`,
    email: email,
    password: 'Aa1!aaaa',
    displayName: 'Confirm User'
  };
  const first = await postRegister(payload);
  expect(first.status).toBe(201);

  // retrieve token via test endpoint
  const tokenRes = await fetch(`${BASE_URL}/api/v1/test/token?email=${encodeURIComponent(email)}`);
  expect(tokenRes.status).toBe(200);
  const token = await tokenRes.text();

  // call confirm
  const confirmRes = await fetch(`${BASE_URL}/api/v1/auth/confirm?token=${encodeURIComponent(token)}`);
  expect(confirmRes.status).toBe(200);

  // verify user enabled
  const userRes = await fetch(`${BASE_URL}/api/v1/test/user?email=${encodeURIComponent(email)}`);
  expect(userRes.status).toBe(200);
  const user = await userRes.json();
  expect(user.enabled).toBe(true);
});

/* Test: メール送信失敗シミュレーション
   - テスト用APIでメール送信を失敗させても登録は成功し、トークンは作成されることを確認する */
test('メール送信失敗時も登録は成功しトークンは作成される', async () => {
  const suffix = randomSuffix();
  const email = `mailfail_${suffix}@ginga.info`;

  // enable simulated mail failure
  await fetch(`${BASE_URL}/api/v1/test/mail/fail?enable=true`, { method: 'POST' });

  const payload = {
    username: `mf_${suffix}`,
    email: email,
    password: 'Aa1!aaaa',
    displayName: 'Mail Fail'
  };
  const res = await postRegister(payload);
  expect(res.status).toBe(201);

  // token should still be created
  const tokenRes = await fetch(`${BASE_URL}/api/v1/test/token?email=${encodeURIComponent(email)}`);
  expect(tokenRes.status).toBe(200);

  // disable simulated failure
  await fetch(`${BASE_URL}/api/v1/test/mail/fail?enable=false`, { method: 'POST' });
});

