            u.setId(100L);
            u.setCreatedAt(Instant.now());
            return u;
        });

        RegisterRequest req = new RegisterRequest();
        req.setUsername("user1");
        req.setEmail("test@ginga.info");
        req.setPassword("P@ssw0rd1");
        req.setDisplayName("テスト");

        // Act
        UserResponse res = authService.register(req);

        // Assert
        assertNotNull(res);
        assertEquals("user1", res.getUsername());
        assertEquals("test@ginga.info", res.getEmail());
        ArgumentCaptor<User> userCap = ArgumentCaptor.forClass(User.class);
        verify(userRepository, times(1)).save(userCap.capture());
        User savedArg = userCap.getValue();
        assertEquals("hashedpwd", savedArg.getPasswordHash());
        assertFalse(savedArg.isEnabled());
        verify(tokenService, times(1)).createTokenForUser(any(User.class));
        // MailService called asynchronously; still verify invocation started
        verify(mailService, times(1)).send(eq("test@ginga.info"), anyString(), anyString());
    }

    @Test
    void register_duplicateUsername_throws() {
        // Verifies that registration with existing username throws DuplicateResourceException and does not save
        // Arrange
        User existing = new User();
        existing.setId(1L);
        when(userRepository.findByUsername("dupuser")).thenReturn(Optional.of(existing));

        RegisterRequest req = new RegisterRequest();
        req.setUsername("dupuser");
        req.setEmail("unique@ginga.info");
        req.setPassword("P@ssw0rd1");

        // Act / Assert
        assertThrows(DuplicateResourceException.class, () -> authService.register(req));
        verify(userRepository, never()).save(any());
    }

    @Test
    void register_duplicateEmail_throws() {
        // Verifies that registration with existing email throws DuplicateResourceException and does not save
        // Arrange
        User existing = new User();
        existing.setId(2L);
        when(userRepository.findByUsername("newuser")).thenReturn(Optional.empty());
        when(userRepository.findByEmail("exists@ginga.info")).thenReturn(Optional.of(existing));

        RegisterRequest req = new RegisterRequest();
        req.setUsername("newuser");
        req.setEmail("exists@ginga.info");
        req.setPassword("P@ssw0rd1");

        // Act / Assert
        assertThrows(DuplicateResourceException.class, () -> authService.register(req));
        verify(userRepository, never()).save(any());
    }
}

package com.ginga.naviai.auth.service;

import com.ginga.naviai.auth.entity.ConfirmationToken;
import com.ginga.naviai.auth.entity.User;
import com.ginga.naviai.auth.repository.ConfirmationTokenRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.Instant;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
public class ConfirmationTokenServiceTest {

    @Mock
    private ConfirmationTokenRepository tokenRepository;

    @InjectMocks
    private ConfirmationTokenService tokenService;

    @Test
    void createTokenForUser_savesTokenAndReturnsString() {
        // Verifies that creating a token persists a ConfirmationToken linked to the user and returns the token string
        User u = new User();
        u.setId(5L);
        ArgumentCaptor<ConfirmationToken> cap = ArgumentCaptor.forClass(ConfirmationToken.class);
        when(tokenRepository.save(any(ConfirmationToken.class))).thenAnswer(inv -> inv.getArgument(0));

        String token = tokenService.createTokenForUser(u);
        assertNotNull(token);
        verify(tokenRepository, times(1)).save(cap.capture());
        ConfirmationToken saved = cap.getValue();
        assertEquals(u, saved.getUser());
        assertNotNull(saved.getExpiresAt());
    }

    @Test
    void findByToken_delegatesToRepository() {
        // Verifies that findByToken delegates to repository and returns the expected token when present
        ConfirmationToken ct = new ConfirmationToken();
        ct.setToken("t1");
        when(tokenRepository.findByToken("t1")).thenReturn(Optional.of(ct));
        Optional<ConfirmationToken> res = tokenService.findByToken("t1");
        assertTrue(res.isPresent());
        assertEquals("t1", res.get().getToken());
    }

    @Test
    void setConfirmedAt_updatesAndSaves() {
        // Verifies that setConfirmedAt updates the ConfirmationToken.confirmedAt and saves it via repository
        ConfirmationToken ct = new ConfirmationToken();
        ct.setToken("t2");
        tokenService.setConfirmedAt(ct, Instant.now());
        verify(tokenRepository, times(1)).save(ct);
        assertNotNull(ct.getConfirmedAt());
    }
}

package com.ginga.naviai.auth.validation;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class StrongPasswordValidatorTest {

    private final StrongPasswordValidator validator = new StrongPasswordValidator();

    @Test
    void validPassword_withThreeCategories_isValid() {
        // Verifies that passwords containing at least three character categories and sufficient length are accepted
        assertTrue(validator.isValid("Abcdef1!", null)); // upper, lower, digit, symbol
        assertTrue(validator.isValid("ABCdefgh1", null)); // upper, lower, digit
        assertTrue(validator.isValid("abcd1!@#A", null));
    }

    @Test
    void invalidPassword_lessThanThreeCategories_or_short_isInvalid() {
        // Verifies that passwords with fewer than three categories or too short (or null) are rejected
        assertFalse(validator.isValid("abcdefg1", null)); // lower+digit only (2 categories)
        assertFalse(validator.isValid("ABCDEFGH", null)); // upper only
        assertFalse(validator.isValid("Ab1!", null)); // too short
        assertFalse(validator.isValid(null, null));
    }
}

